add(DR,"role",[
("headlights","easy","When does Minnesota law require headlights?","¿Cuándo exige la ley de Minnesota encender los faros?",["Sunset to sunrise, in rain/snow/sleet/hail, or when you can't see 500 feet","Only after midnight","Only on highways","Only in fog"],["Del atardecer al amanecer, con lluvia, nieve, aguanieve o granizo, o si no ves a 500 pies","Solo después de medianoche","Solo en autopista","Solo con neblina"],"MN Stat. 169.48.","Estatuto 169.48 de MN.",HL),
("headlights","med","It's 2 p.m. and lightly snowing. Do you need headlights on in Minnesota?","Son las 2 p. m. y nieva poco. ¿Debes llevar faros encendidos en Minnesota?",["Yes — snow requires headlights","No, it's daytime","Only parking lights","Only if it's heavy"],["Sí; con nieve son obligatorios","No, es de día","Solo cuartos","Solo si es fuerte"],"169.48 requires headlights during snow, rain, sleet or hail.","El 169.48 exige faros con nieve, lluvia, aguanieve o granizo.",HL),
("headlights","med","When must you dim your high beams for an oncoming car?","¿Cuándo debes bajar las luces altas por un carro que viene?",["Within 1,000 feet of the oncoming vehicle","Within 50 feet","Never","Only in town"],["A 1,000 pies del vehículo que viene","A 50 pies","Nunca","Solo en la ciudad"],"MN 169.61: dim within 1,000 ft of oncoming and 200 ft when following.","MN 169.61: baja a 1,000 pies de quien viene y a 200 si vas detrás.","https://www.revisor.mn.gov/statutes/cite/169.61"),
("move_over","easy","A squad car with flashing lights is stopped on the shoulder. What must you do?","Una patrulla con luces está detenida en el acotamiento. ¿Qué debes hacer?",["Move over a lane if safe; if you can't, slow down","Keep your speed and lane","Speed up to pass quickly","Honk"],["Cambiarte de carril si es seguro; si no puedes, bajar la velocidad","Seguir igual","Acelerar para pasar rápido","Tocar el claxon"],"MN Move Over law (169.18), the Ted Foss law.","Ley 'Move Over' de MN (169.18), Ley Ted Foss.",MO),
("move_over","med","Does Minnesota's Move Over law apply to a regular car stopped with hazard lights on?","¿La ley 'Move Over' de MN aplica a un carro común detenido con intermitentes?",["Yes — also for stalled vehicles with hazards or people outside","No, only police","Only tow trucks","Only on I-494"],["Sí; también a vehículos detenidos con intermitentes o gente afuera","No, solo policía","Solo grúas","Solo en la I-494"],"The law was expanded to stalled vehicles with hazard lights or people outside.","La ley se amplió a vehículos detenidos con intermitentes o gente afuera.","https://dps.mn.gov/divisions/ots/move-over"),
("hands_free","easy","Under Minnesota's hands-free law, can you hold your phone at a red light?","Según la ley de manos libres de MN, ¿puedes sostener el celular en un alto?",["No — it applies whenever you're driving, including stopped in traffic","Yes, at red lights","Yes, under 5 mph","Only for texting"],["No; aplica siempre que manejas, incluso detenido en el tráfico","Sí, en el alto","Sí, a menos de 5 mph","Solo para mensajes"],"MN DPS: no holding the phone while driving, including at stoplights.","DPS de MN: no sostener el celular manejando, ni en semáforos.",HF),
("hands_free","med","Which phone use is allowed while driving the shuttle in Minnesota?","¿Qué uso del celular se permite al manejar el shuttle en MN?",["One-touch voice calls or GPS in hands-free mode","Texting at stops","Watching a video","Scrolling social media"],["Llamadas o GPS con un toque en modo manos libres","Mandar mensajes en los altos","Ver videos","Ver redes sociales"],"MN law allows one-touch/voice activation; no texting, video or scrolling.","La ley permite activar con un toque o voz; no mensajes, videos ni redes.",HF),
("hands_free","hard","What's the exception that lets a driver hold a phone in Minnesota?","¿Qué excepción permite sostener el celular al manejar en MN?",["Calling 911 in an emergency","Checking a guest's flight","Being late","Taking a photo of traffic"],["Llamar al 911 en una emergencia","Revisar el vuelo de un huésped","Ir tarde","Tomar foto del tráfico"],"Emergency calls are the key exception.","Las llamadas de emergencia son la excepción principal.",HF),
("seatbelts","easy","Who in the shuttle must wear a seat belt in Minnesota?","¿Quién debe usar cinturón en el shuttle en Minnesota?",["The driver and all passengers in every seat with a belt","Only the driver","Only front seat","Nobody under 20 mph"],["El chofer y todos los pasajeros en asientos con cinturón","Solo el chofer","Solo adelante","Nadie a menos de 20 mph"],"MN 169.686 requires belts for driver and passengers in all seats.","El 169.686 exige cinturón para chofer y pasajeros en todos los asientos.",SB),
("school_bus","easy","A school bus stops with red lights flashing and stop arm out. What do you do?","Un autobús escolar se detiene con luces rojas y el brazo de alto. ¿Qué haces?",["Stop at least 20 feet away and wait until lights stop and the arm is in","Pass slowly","Honk and pass","Only stop if kids are visible"],["Detenerte al menos a 20 pies y esperar a que apague luces y guarde el brazo","Pasar despacio","Tocar el claxon y pasar","Solo parar si ves niños"],"MN 169.444: stop at least 20 ft away.","MN 169.444: detente al menos a 20 pies.",SCH),
("pedestrians","easy","A pedestrian is in a crosswalk at an intersection without a signal. What must you do?","Un peatón está en el cruce en una esquina sin semáforo. ¿Qué haces?",["Stop and let them cross","Honk","Go around them","Speed up"],["Detenerte y dejarlo cruzar","Tocar el claxon","Rodearlo","Acelerar"],"MN 169.21: drivers must stop for pedestrians in crosswalks.","MN 169.21: hay que parar por peatones en el cruce.",PED),
("pedestrians","med","A car is stopped at a crosswalk in the lane next to you. What should you do?","Un carro está detenido en el cruce en el carril de al lado. ¿Qué haces?",["Don't pass it — someone may be crossing","Pass it quickly","Honk at it","Change lanes and keep going"],["No rebasarlo; alguien podría estar cruzando","Rebasarlo rápido","Tocarle el claxon","Cambiarte y seguir"],"MN law prohibits passing a vehicle stopped for a pedestrian.","La ley prohíbe rebasar a un vehículo detenido por un peatón.",PED),
("speed","med","What's the speed limit in a Minnesota urban district unless posted otherwise?","¿Cuál es el límite en zona urbana de MN si no hay letrero?",["30 mph","45 mph","55 mph","20 mph"],["30 mph","45 mph","55 mph","20 mph"],"MN 169.14: 30 mph in urban districts.","MN 169.14: 30 mph en zonas urbanas.",SP),
("speed","easy","It's snowing hard and the limit is 65. What speed is legal?","Nieva fuerte y el límite es 65. ¿Qué velocidad es legal?",["A speed safe for conditions — often well under the limit","65 is always fine","70 to keep up","Exactly 55"],["Una velocidad segura para las condiciones, muchas veces muy por debajo","65 siempre está bien","70 para seguir el ritmo","Exacto 55"],"MN 169.14: no driver may drive faster than is reasonable for conditions.","MN 169.14: no se maneja más rápido de lo razonable para las condiciones.",SP),
("following","med","On dry roads, what following distance should you keep?","En pavimento seco, ¿qué distancia de seguimiento debes guardar?",["At least 3 seconds — more in bad weather or with a van full","1 second","Bumper to bumper","10 feet"],["Al menos 3 segundos; más con mal clima o van llena","1 segundo","Pegado","10 pies"],"The 3-second rule is the standard in the MN Driver's Manual.","La regla de 3 segundos es la del Manual del Conductor de MN.",DVS),
("winter","easy","Before a winter drive, how much snow should you clear off the van?","Antes de manejar en invierno, ¿cuánta nieve debes quitar de la van?",["All windows, mirrors, lights and the roof","Just a small hole in the windshield","Only the driver window","None — it blows off"],["Todas las ventanas, espejos, luces y el techo","Solo un hoyito en el parabrisas","Solo la ventana del chofer","Nada, se vuela"],"MnDOT/DPS urge clearing all snow and ice so you can see and be seen.","MnDOT y DPS piden quitar toda la nieve y hielo para ver y ser visto.",WIN),
("winter","med","A snowplow is ahead of you. What's safest?","Hay un quitanieves adelante. ¿Qué es lo más seguro?",["Stay well back and don't pass on the right","Pass quickly on the right","Follow close in its tracks","Flash your lights at it"],["Mantente lejos y no rebases por la derecha","Rebasar rápido por la derecha","Seguirlo pegado","Echarle luces"],"MnDOT: stay back from plows and never pass on the right.","MnDOT: mantente lejos y nunca rebases por la derecha.",WIN),
("winter","med","Where does black ice form first?","¿Dónde se forma primero el hielo negro?",["Bridges, overpasses and shaded spots","Sunny parking lots","Gravel roads only","Inside garages"],["Puentes, pasos elevados y zonas de sombra","Estacionamientos con sol","Solo caminos de grava","Dentro de cocheras"],"Bridges and overpasses freeze before other road surfaces.","Los puentes se congelan antes que el resto del camino.",WIN),
("winter","hard","Your van starts to skid on ice. What should you do?","Tu van empieza a patinar en hielo. ¿Qué haces?",["Ease off the gas and steer gently where you want to go","Slam the brakes","Turn the wheel hard the other way","Accelerate"],["Soltar el acelerador y girar suave hacia donde quieres ir","Frenar de golpe","Girar fuerte al lado contrario","Acelerar"],"Standard skid recovery: off the gas, steer smoothly, no hard braking.","Para salir de un derrape: suelta el acelerador, gira suave, sin frenar fuerte.",DVS),
("winter","med","With ABS brakes, how do you stop hard on ice?","Con frenos ABS, ¿cómo frenas fuerte en hielo?",["Press firmly and hold — don't pump","Pump the brakes fast","Use the parking brake","Shift to neutral"],["Presionar firme y mantener; no bombear","Bombear rápido","Usar el freno de mano","Poner neutral"],"NHTSA: with ABS, apply firm, steady pressure.","NHTSA: con ABS, presión firme y constante.",NHTSA),
("winter","easy","What should the shuttle carry in a Minnesota winter?","¿Qué debe llevar el shuttle en invierno en Minnesota?",["Scraper/brush, blanket, and extra washer fluid","Only sunglasses","Nothing extra","A beach umbrella"],["Raspador/cepillo, cobija y líquido limpiaparabrisas extra","Solo lentes oscuros","Nada extra","Una sombrilla de playa"],"MN DPS winter-kit guidance.","Guía de kit invernal de DPS MN.",WIN),
("tires","med","Why check tire pressure more often in winter?","¿Por qué revisar la presión de llantas más seguido en invierno?",["Cold air lowers tire pressure","Tires grow in the cold","It doesn't change","Snow inflates them"],["El frío baja la presión","Las llantas crecen con el frío","No cambia","La nieve las infla"],"NHTSA: pressure drops as temperatures fall.","NHTSA: la presión baja con el frío.",TIRE),
("tires","easy","Where do you find the right tire pressure for the van?","¿Dónde está la presión correcta para la van?",["The sticker in the driver's door jamb or the owner's manual","The number on the tire sidewall (max)","Guess 50 psi","The gas station sign"],["La etiqueta en el marco de la puerta del chofer o el manual","El número máximo del costado de la llanta","Calcular 50 psi","El letrero de la gasolinera"],"NHTSA: use the vehicle placard, not the sidewall max.","NHTSA: usa la etiqueta del vehículo, no el máximo de la llanta.",TIRE),
("pretrip","easy","Before your first run, what's a quick walk-around check?","Antes del primer viaje, ¿qué se revisa al rodear la van?",["Tires, lights, mirrors, leaks and windows","Only the radio","Only the gas cap","Nothing"],["Llantas, luces, espejos, fugas y vidrios","Solo el radio","Solo el tapón","Nada"],"A pre-trip inspection catches problems before passengers board.","La revisión previa detecta problemas antes de subir pasajeros.",FMCSA),
("pretrip","med","You find a warning light on the dash before a run. What do you do?","Antes de salir ves un foco de advertencia prendido. ¿Qué haces?",["Report it to your manager before driving","Ignore it","Cover it with tape","Drive faster to finish"],["Reportarlo a tu gerente antes de manejar","Ignorarlo","Taparlo con cinta","Manejar más rápido"],"Unsafe vehicle conditions should be reported and fixed before service.","Las fallas se reportan y se arreglan antes de dar servicio.",FMCSA),
("drowsy","med","Which is a sign you're too drowsy to drive?","¿Cuál es señal de que tienes demasiado sueño para manejar?",["Drifting from your lane or missing exits","Feeling hungry","Singing","Being early"],["Salirte del carril o pasarte salidas","Tener hambre","Cantar","Llegar temprano"],"NHTSA drowsy-driving warning signs.","Señales de manejo con sueño, NHTSA.",DRW),
("distracted","easy","A passenger hands you a phone to look at an address while driving. What do you do?","Un pasajero te da su celular para ver una dirección mientras manejas. ¿Qué haces?",["Pull over safely first, or have them read it out","Look while driving","Hold it on the wheel","Speed up and look"],["Orillarte primero, o que te la lea","Verlo manejando","Ponerlo en el volante","Acelerar y ver"],"NHTSA: any visual distraction raises crash risk.","NHTSA: cualquier distracción visual aumenta el riesgo.",DIS),
("dui","easy","What is Minnesota's legal alcohol limit (BAC) for drivers 21+?","¿Cuál es el límite legal de alcohol (BAC) en MN para mayores de 21?",["0.08","0.15","0.20","No limit"],["0.08","0.15","0.20","No hay límite"],"MN 169A.20: 0.08. For work, the rule is zero.","MN 169A.20: 0.08. En el trabajo, la regla es cero.",DUI),
("dui","med","Can you drive the shuttle after taking a medicine that says 'may cause drowsiness'?","¿Puedes manejar el shuttle después de tomar medicina que dice 'puede causar sueño'?",["No — tell your manager; impaired is impaired","Yes, it's legal medicine","Yes, with coffee","Only short trips"],["No; avisa a tu gerente; afectado es afectado","Sí, es medicina legal","Sí, con café","Solo viajes cortos"],"MN DWI law covers impairment by drugs, including some prescriptions.","La ley de MN cubre la afectación por drogas, incluso recetadas.",DUI),
("passengers","easy","Where should guests stand while you load bags?","¿Dónde deben estar los huéspedes mientras subes maletas?",["On the curb, away from the van's path","Behind the van","In the driving lane","On the bumper"],["En la banqueta, lejos del paso de la van","Detrás de la van","En el carril","En la defensa"],"Keeping people clear of the vehicle prevents backing injuries.","Mantenerlos lejos evita accidentes al dar reversa.",BP),
("passengers","med","A guest wants to stand while the shuttle moves because it's a short ride. What do you say?","Un huésped quiere ir parado porque el viaje es corto. ¿Qué le dices?",["Ask them to sit and buckle before you move","It's fine","Hold the door","Only on the highway"],["Pedirle que se siente y se abroche antes de avanzar","Está bien","Que se agarre de la puerta","Solo en autopista"],"Seated and belted is required (169.686) and safest.","Ir sentado con cinturón es obligatorio (169.686) y más seguro.",SB),
("passengers","med","A guest in a wheelchair needs the shuttle and we can't take it. What's the right step?","Un huésped en silla de ruedas necesita el shuttle y no podemos llevarlo. ¿Qué es lo correcto?",["Tell your manager right away so equivalent accessible transport can be arranged","Tell them no","Make them wait until tomorrow","Charge them extra"],["Avisar de inmediato al gerente para conseguir transporte accesible equivalente","Decirle que no","Que espere a mañana","Cobrarle extra"],"ADA requires equivalent service for guests with disabilities on hotel shuttles.","La ADA exige servicio equivalente para huéspedes con discapacidad.","https://www.ada.gov/resources/shuttle-service/"),
("passengers","easy","How should you help a guest with a cane step into the van?","¿Cómo ayudas a un huésped con bastón a subir a la van?",["Ask how they'd like help, and offer an arm","Grab them and lift","Rush them","Don't offer"],["Preguntar cómo quiere ayuda y ofrecer el brazo","Agarrarlo y cargarlo","Apurarlo","No ofrecer"],"Always ask before helping — people know what works for them.","Siempre pregunta antes de ayudar.",BP),
("airport","med","Where do hotel shuttles pick up at MSP?","¿Dónde recogen los shuttles de hotel en MSP?",["The designated hotel shuttle area in the ground transportation center","Any curb at departures","In the parking ramp roof","On Hwy 5"],["En la zona designada de shuttles de hotel en el centro de transporte terrestre","En cualquier banqueta de salidas","En el techo del estacionamiento","En la Hwy 5"],"MSP directs hotel shuttles to designated ground-transportation pickup areas.","MSP manda los shuttles a las zonas designadas de transporte terrestre.",AIR),
("airport","easy","A guest calls for pickup from MSP. What info do you need?","Un huésped pide que lo recojan en MSP. ¿Qué datos necesitas?",["Name, terminal (1 or 2), number in the party and bags","Only their name","Their credit card","Their flight's meal"],["Nombre, terminal (1 o 2), cuántas personas y maletas","Solo el nombre","Su tarjeta","La comida del vuelo"],"MSP has Terminal 1 and Terminal 2 — knowing which saves time.","MSP tiene Terminal 1 y 2; saber cuál ahorra tiempo.",AIR),
("airport","med","Which airlines use MSP Terminal 2?","¿Qué aerolíneas usan la Terminal 2 de MSP?",["Mainly Sun Country and Southwest (check the MSP site — it can change)","Delta","All airlines","No passenger flights"],["Principalmente Sun Country y Southwest (revisa la página de MSP; puede cambiar)","Delta","Todas","Ningún vuelo de pasajeros"],"MSP lists Sun Country and Southwest at Terminal 2; Delta is at Terminal 1.","MSP indica Sun Country y Southwest en Terminal 2; Delta en Terminal 1.","https://www.mspairport.com/airlines-and-flights/airlines"),
("backing","easy","What's the safest way to back up the van?","¿Cuál es la forma más segura de dar reversa?",["Check around first, back slowly, use a spotter if you can't see","Back fast","Rely only on the camera","Honk and go"],["Revisar alrededor, reversa lenta y con alguien guiando si no ves","Reversa rápida","Solo la cámara","Tocar el claxon y listo"],"Most low-speed crashes happen backing; walk around and go slow.","Muchos choques son en reversa; revisa y ve despacio.",NHTSA),
("crash","med","You have a minor fender-bender with guests on board. First step?","Tienes un choque leve con huéspedes a bordo. ¿Primer paso?",["Check for injuries, call 911 if needed, then call your manager","Drive away","Argue with the other driver","Post photos online"],["Revisar lesionados, llamar al 911 si hace falta y luego al gerente","Irte","Discutir con el otro","Subir fotos"],"MN law requires stopping and exchanging info; safety first.","La ley de MN exige parar e intercambiar datos; primero la seguridad.","https://www.revisor.mn.gov/statutes/cite/169.09"),
("crash","hard","After a crash in Minnesota with injury or $1,000+ damage, who must be notified?","Tras un choque en MN con lesionados o daños de $1,000 o más, ¿a quién se avisa?",["Police right away (and a written report to DPS within 10 days)","Only your insurance","No one","Only the guest"],["A la policía de inmediato (y reporte escrito a DPS en 10 días)","Solo al seguro","A nadie","Solo al huésped"],"MN 169.09: report to police; written report within 10 days for injury or $1,000+.","MN 169.09: aviso a la policía; reporte escrito en 10 días con lesiones o $1,000+.","https://www.revisor.mn.gov/statutes/cite/169.09"),
("fuel","easy","Why not let the shuttle's tank run low in winter?","¿Por qué no dejar el tanque bajo en invierno?",["You may get stuck in traffic or cold, and condensation can freeze lines","It's lighter","It saves money","No reason"],["Te puedes quedar atorado con frío, y la humedad puede congelar líneas","Pesa menos","Ahorra dinero","Por nada"],"Keeping at least half a tank is common winter advice.","Mantener al menos medio tanque es consejo común de invierno.",WIN),
("idling","easy","You wait 15 minutes at the airport curb. Should you leave the van running and walk away?","Esperas 15 minutos en el aeropuerto. ¿Dejas la van prendida y te alejas?",["No — never leave it running unattended","Yes, to keep it warm","Yes, with doors open","Only at night"],["No; nunca la dejes prendida sola","Sí, para que esté caliente","Sí, con puertas abiertas","Solo de noche"],"An unattended running vehicle can be stolen or roll.","Un vehículo prendido y solo puede ser robado o moverse.",BP),
("lane","med","A deer jumps in front of the van. What does MN DPS advise?","Un venado salta frente a la van. ¿Qué aconseja DPS de MN?",["Brake firmly and stay in your lane — don't swerve","Swerve into the ditch","Speed up","Turn into oncoming traffic"],["Frenar firme y quedarte en tu carril; no volantear","Volantear a la cuneta","Acelerar","Irte al carril contrario"],"Swerving often causes worse crashes than hitting the deer.","Volantear causa choques peores que pegarle al venado.",DOT),
("work_zone","easy","In a work zone with workers present, what applies?","En una zona de obras con trabajadores, ¿qué aplica?",["Slow down, follow signs, no phone — fines can double","Normal speed","Pass on the shoulder","Honk at workers"],["Baja la velocidad, sigue letreros, sin celular; multas pueden duplicarse","Velocidad normal","Rebasar por el acotamiento","Pitarles a los trabajadores"],"MnDOT work-zone rules.","Reglas de zonas de obra de MnDOT.","https://www.dot.state.mn.us/workzone/"),
("roundabout","med","Entering a roundabout, who has the right of way?","Al entrar a una glorieta, ¿quién tiene preferencia?",["Traffic already in the roundabout","You do","Whoever is faster","Trucks only"],["Los que ya están en la glorieta","Tú","El más rápido","Solo camiones"],"MnDOT: yield to traffic in the roundabout.","MnDOT: cede el paso a quien ya circula.","https://www.dot.state.mn.us/roundabouts/"),
("zipper","med","MnDOT's 'zipper merge' for a lane closure means…","El 'zipper merge' de MnDOT en un cierre de carril significa…",["Use both lanes to the merge point, then take turns","Merge as early as possible","Block the closed lane","Speed up to cut in"],["Usar ambos carriles hasta el punto de unión y turnarse","Unirse lo antes posible","Bloquear el carril cerrado","Acelerar para meterse"],"MnDOT promotes the late, alternating zipper merge in heavy traffic.","MnDOT promueve unirse al final y turnarse con tráfico pesado.","https://www.dot.state.mn.us/zippermerge/"),
("emergency_veh","easy","An ambulance with siren comes up behind you. What do you do?","Una ambulancia con sirena viene atrás. ¿Qué haces?",["Pull to the right and stop until it passes","Speed up","Stop in the lane","Keep going"],["Orillarte a la derecha y parar hasta que pase","Acelerar","Parar en el carril","Seguir"],"MN 169.20: yield and pull right for emergency vehicles.","MN 169.20: cede el paso y orillate a la derecha.","https://www.revisor.mn.gov/statutes/cite/169.20"),
("right_on_red","med","Is right turn on red allowed in Minnesota?","¿Se permite vuelta a la derecha en rojo en Minnesota?",["Yes, after a full stop, unless a sign prohibits it","Never","Without stopping","Only at night"],["Sí, después de alto total, salvo letrero que lo prohíba","Nunca","Sin parar","Solo de noche"],"MN 169.06 permits right on red after stopping unless posted.","MN 169.06 lo permite tras alto total, salvo letrero.","https://www.revisor.mn.gov/statutes/cite/169.06"),
("guests","easy","Should you discuss guest names or room numbers out loud in the van?","¿Debes decir nombres o números de cuarto en voz alta en la van?",["No — keep guest info private","Yes, to be friendly","Only room numbers","Only at night"],["No; la información del huésped es privada","Sí, para ser amable","Solo el número","Solo de noche"],"Guest privacy applies in the shuttle too.","La privacidad del huésped aplica en el shuttle también.",BP),
("guests","med","A guest leaves a bag in the van. What do you do?","Un huésped deja una bolsa en la van. ¿Qué haces?",["Bring it to the front desk and log it in lost and found","Keep it","Leave it in the van","Open it and use it"],["Llevarla a recepción y registrarla en objetos perdidos","Quedártela","Dejarla en la van","Abrirla y usarla"],"Items go to lost and found so the guest can be contacted.","Los objetos van a objetos perdidos para contactar al huésped.",BP),
("tips","easy","A guest asks if the shuttle is free. What do you say (at hotels with a free shuttle)?","Un huésped pregunta si el shuttle es gratis. ¿Qué dices (en hoteles con shuttle gratis)?",["Yes, it's complimentary","$10 a person","Only for members","Ask the airport"],["Sí, es gratis","$10 por persona","Solo para miembros","Pregunte en el aeropuerto"],"Our airport-area hotels list a complimentary shuttle.","Nuestros hoteles del aeropuerto ofrecen shuttle gratis.",BP),
("weather","med","Freezing rain is forecast for your morning runs. What's smart?","Pronostican lluvia helada para tus viajes de la mañana. ¿Qué es lo mejor?",["Check 511 and talk to your manager about timing — leave extra time","Drive faster to beat it","Skip the pre-trip","Use cruise control"],["Revisar el 511 y hablar con tu gerente; salir con más tiempo","Manejar más rápido","Saltarte la revisión","Usar control de crucero"],"MnDOT 511 has road conditions; never use cruise control on ice.","El 511 de MnDOT da condiciones; nunca uses crucero en hielo.","https://511mn.org/"),
("weather","easy","Should you use cruise control on snowy or icy roads?","¿Debes usar control de crucero en nieve o hielo?",["No","Yes, it's smoother","Only uphill","Only at night"],["No","Sí, es más suave","Solo en subida","Solo de noche"],"Cruise control can make you lose control on slippery roads.","El crucero puede hacerte perder el control en caminos resbalosos.",WIN),
("mirrors","easy","When should you adjust your mirrors?","¿Cuándo ajustas los espejos?",["Before you start driving","While on the highway","Never","After a crash"],["Antes de empezar a manejar","En la autopista","Nunca","Después de un choque"],"Adjust seat and mirrors before moving.","Ajusta asiento y espejos antes de avanzar.",DVS),
("blind_spot","med","How do you check a blind spot before changing lanes?","¿Cómo revisas el punto ciego antes de cambiar de carril?",["Signal, check mirrors, then a quick look over your shoulder","Just the mirror","Just the signal","Honk first"],["Direccional, espejos y una vista rápida sobre el hombro","Solo el espejo","Solo la direccional","Pitar primero"],"MN Driver's Manual: shoulder check before lane changes.","Manual de MN: voltea sobre el hombro antes de cambiar de carril.",DVS),
("signal","easy","How far ahead must you signal a turn in Minnesota?","¿Con cuánta anticipación debes poner la direccional en MN?",["At least 100 feet","10 feet","At the turn","No need"],["Al menos 100 pies","10 pies","En la vuelta","No es necesario"],"MN 169.19: signal at least 100 feet before turning.","MN 169.19: direccional al menos 100 pies antes.","https://www.revisor.mn.gov/statutes/cite/169.19"),
("loading","med","How should heavy bags be placed in the shuttle?","¿Cómo se acomodan las maletas pesadas en el shuttle?",["Low, secured, and out of the aisle","On the seats stacked high","In the aisle","On the dash"],["Abajo, aseguradas y fuera del pasillo","En los asientos, apiladas","En el pasillo","En el tablero"],"Loose heavy items become projectiles in a sudden stop.","Las maletas sueltas salen volando al frenar.",BP),
("lifting","med","How do you lift a heavy suitcase into the van safely?","¿Cómo subes una maleta pesada a la van sin lastimarte?",["Bend your knees, keep it close, don't twist — ask for help if needed","Yank it with one arm","Twist at the waist","Throw it in"],["Doblar rodillas, pegarla al cuerpo, sin girar; pedir ayuda si hace falta","Jalarla con un brazo","Girar la cintura","Aventarla"],"OSHA safe-lifting basics.","Bases de levantamiento seguro de OSHA.",LIFT),
("parking","easy","Where should you never stop the shuttle to drop guests?","¿Dónde nunca debes parar el shuttle para bajar huéspedes?",["In a fire lane or crosswalk","At the hotel entrance","At the airport shuttle area","In a marked loading zone"],["En carril de bomberos o paso peatonal","En la entrada del hotel","En la zona de shuttles","En zona de carga marcada"],"Fire lanes and crosswalks must be kept clear.","Los carriles de bomberos y cruces deben estar libres.",BP),
("child","hard","A family wants their 3-year-old to ride on a lap in the shuttle. What's the rule in MN?","Una familia quiere llevar a su niño de 3 años en las piernas. ¿Qué dice la ley de MN?",["Kids under 8 and under 4'9\" must be in a proper child restraint","Laps are fine","Only on the highway","No rule"],["Los menores de 8 años y de menos de 4'9\" deben ir en asiento infantil","En las piernas está bien","Solo en autopista","No hay regla"],"MN 169.685: child passenger restraints.","MN 169.685: sistemas de retención infantil.","https://www.revisor.mn.gov/statutes/cite/169.685"),
])
